package com.gameaggregator.publisherservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.publisherservice.application.PublisherService;import com.gameaggregator.publisherservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/publishers") public class PublisherController{final PublisherService s;public PublisherController(PublisherService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) ApiResponse<Publisher> create(@Valid @RequestBody PublisherDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<Publisher>> list(){return ApiResponse.success(s.list());}@GetMapping("/{id}") ApiResponse<Publisher> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PutMapping("/{id}") ApiResponse<Publisher> update(@PathVariable UUID id,@Valid @RequestBody PublisherDtos.Update r){return ApiResponse.success(s.update(id,r));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){s.delete(id);}@PostMapping("/{id}/team") ApiResponse<PublisherTeamMember> team(@PathVariable UUID id,@Valid @RequestBody PublisherDtos.Team r){return ApiResponse.success(s.team(id,r));}@PostMapping("/{id}/distribution-rights") ApiResponse<DistributionRight> right(@PathVariable UUID id,@Valid @RequestBody PublisherDtos.Right r){return ApiResponse.success(s.right(id,r));}@GetMapping("/{id}/distribution-rights") ApiResponse<List<DistributionRight>> rights(@PathVariable UUID id){return ApiResponse.success(s.rights(id));}}
